#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>

#ifndef ROWS_PER_BLOCK
#define ROWS_PER_BLOCK 16
#endif

template<int RPB>
__global__ __launch_bounds__(RPB*32, 2)
void gemv_warp_rows_kernel(const __nv_bfloat16* __restrict__ x,
                           const __nv_bfloat16* __restrict__ W,
                           __nv_bfloat16* __restrict__ y,
                           int N, int K) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int wr = tid >> 5;
    int row = blockIdx.x * RPB + wr;
    if (row >= N) return;
    const __nv_bfloat16* wrow = W + (long long)row * K;
    float sum = 0.0f;
    int k = lane;
    // unroll by 4 warp-strides
    for (; k + 96 < K; k += 128) {
        float x0 = __bfloat162float(x[k]);
        float w0 = __bfloat162float(wrow[k]);
        float x1 = __bfloat162float(x[k+32]);
        float w1 = __bfloat162float(wrow[k+32]);
        float x2 = __bfloat162float(x[k+64]);
        float w2 = __bfloat162float(wrow[k+64]);
        float x3 = __bfloat162float(x[k+96]);
        float w3 = __bfloat162float(wrow[k+96]);
        sum = fmaf(x0, w0, sum);
        sum = fmaf(x1, w1, sum);
        sum = fmaf(x2, w2, sum);
        sum = fmaf(x3, w3, sum);
    }
    for (; k < K; k += 32) {
        sum = fmaf(__bfloat162float(x[k]), __bfloat162float(wrow[k]), sum);
    }
    // warp reduction
    sum += __shfl_down_sync(0xffffffff, sum, 16);
    sum += __shfl_down_sync(0xffffffff, sum, 8);
    sum += __shfl_down_sync(0xffffffff, sum, 4);
    sum += __shfl_down_sync(0xffffffff, sum, 2);
    sum += __shfl_down_sync(0xffffffff, sum, 1);
    if (lane == 0) y[row] = __float2bfloat16_rn(sum);
}

torch::Tensor gemv_bf16_cuda(torch::Tensor x, torch::Tensor W) {
    const int64_t N64 = W.size(0);
    const int64_t K64 = W.size(1);
    auto y = torch::empty({N64}, x.options());
    if (N64 == 0) return y;
    int N = (int)N64;
    int K = (int)K64;
    dim3 block(ROWS_PER_BLOCK * 32);
    dim3 grid((N + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK);
